import { useId } from "react";

export const Logo = () => {
  const logoId = useId().replaceAll(":", "");
  const patternId = `headpan-pattern-${logoId}`;
  const imageId = `headpan-image-${logoId}`;

  return <svg
    width="90"
    height="32"
    viewBox="0 0 122 32"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    xmlnsXlink="http://www.w3.org/1999/xlink"
  >
    <rect width="122" height="32" fill={`url(#${patternId})`} />
    <defs>
      <pattern
        id={patternId}
        patternContentUnits="objectBoundingBox"
        width="1"
        height="1"
      >
        <use
          xlinkHref={`#${imageId}`}
          transform="matrix(0.000577742 0 0 0.00220264 -0.0110132 0)"
        />
      </pattern>
      <image
        id={imageId}
        width="1769"
        height="454"
        preserveAspectRatio="none"
        xlinkHref="data:image/png;base64,"
      />
    </defs>
  </svg>;
};

